{
  "command": "sh -c 'awk -v FILE=\"/etc/ssh/sshd_config\"\\n    BEGIN { found=0 }\\n    /^#/ { next }\\n    /^[[:space:]]*$/ { next }\\n    {\\n        gsub(/^[[:space:]]*/, \"\");\\n        gsub(/[[:space:]]*$/, \"\");\\n        if ($0 == \"\") next\\n    {\\n            split($0, a, \"=\")\\n            key = a[1];\\n            val = a[2];\\n            if (tolower(key) == \"gssapiauthentication\") {\\n            print \"GSSAPIAuthentication no\";\\n            found=1;\\n    }\\n        else { print $0 }\\n    }\\n    END {\\n        if (!found) print \"GSSAPIAuthentication no\"\\n    }\\n    }\\n    > \"/tmp/sshd_tmp\" && mv \"/tmp/sshd_tmp\" \"/etc/ssh/sshd_config\"\\n"
}

